package qkd.multiband;

import java.io.Serializable;

/**
 * Spontaneous Raman scattering (SpRS) generated by classical channels and collected in the band of a quantum
 * channel (QCh).
 *
 * <p><b>Cross-section.</b> The SpRS cross-section rho, in 1/(km nm), is the fraction of the pump power scattered
 * per km of fibre into one nm around the QCh wavelength. Its spectral shape follows the Raman gain profile with the
 * Bose-Einstein population factor of the phonons:</p>
 * <pre>
 *   rho(nu_p, nu_q) = K * g0(|dnu|) * B(dnu) * (c / lambda_q^2) * 1e-9 * (nu_p / nu_1550)
 *   dnu = nu_p - nu_q,   B = n_th + 1 (Stokes, dnu &gt; 0),   B = n_th (anti-Stokes, dnu &lt; 0)
 *   n_th = 1 / (exp(h |dnu| / (k T)) - 1)
 * </pre>
 * <p>g0 is the SSMF gain profile of {@link RamanGainProfile}, c/lambda^2 * 1e-9 converts from per-Hz to per-nm and
 * the last factor is the nu_p scaling of the Raman cross-section. The scale K was fitted by least squares to the
 * measured cross-section of [ERAERDS10] (Fig. 1, pump at 1550 nm, SSMF, room temperature): the model stays within
 * about 10% of the measurement from -5 to +11 THz (ratio 0.86 to 1.08), which is the accuracy targeted by the
 * verification VMB-2.</p>
 *
 * <p><b>Propagation.</b> The power collected at the QCh receiver is P = P_0 * rho * d_lambda * G, where P_0 is the
 * launch power of the classical channel, d_lambda the QCh filter width in nm and G an <i>effective length</i> in km
 * for co-propagating channels. The methods of this class return G (all losses in neper/km):</p>
 * <ul>
 *   <li>forward, same core (co-propagating): G = (e^{-a_q L} - e^{-a_c L}) / (a_c - a_q) [KAWAHARA11], [ERAERDS10]
 *       eq. 2; the simpler form G = L e^{-a L} used by [MEHDI24] and [DIBAJ25] is the a_q = a_c limit;</li>
 *   <li>forward from a <i>neighbour</i> core of a weakly coupled MCF (power coupling coefficient h in
 *       1/km): [CAI20] eqs. 11 and 18, with both paths (crosstalk then SpRS, SpRS then crosstalk) included.</li>
 * </ul>
 *
 * <p>The object is immutable and thread-safe; the effective lengths are static and allocation-free so that they can
 * be called once per (link, active classical channel) inside the simulator.</p>
 *
 * <p>Referências: [ERAERDS10] P. Eraerds et al., "Quantum key distribution and 1 Gbps data encryption over a
 * single fibre", New J. Phys. 12, 063027, 2010; [KAWAHARA11] H. Kawahara et al., "Effect of spontaneous Raman
 * scattering on quantum channel wavelength-multiplexed with classical channel", Opt. Commun. 284, 691, 2011;
 * [CAI20] C. Cai, Y. Sun, Y. Ji, "Intercore spontaneous Raman scattering impact on quantum key distribution in
 * multicore fiber", New J. Phys. 22, 083020, 2020; [MEHDI24] P. Mehdizadeh et al., IEEE Commun. Lett. 28(3), 2024;
 * [DIBAJ25] M. R. Dibaj et al., JLT 43(1), 2025; [GNPY] perfil g0 em {@link RamanGainProfile}; [CHAPURAN09] T. E.
 * Chapuran et al., New J. Phys. 11, 105001, 2009 (Tabela 1); [NWEKE05] N. I. Nweke et al., Appl. Phys. Lett. 87,
 * 174103, 2005; [HOLLENBECK02] D. Hollenbeck, C. D. Cantrell, JOSA B 19(12), 2886, 2002.</p>
 */
public final class SpontaneousRamanModel implements Serializable {

    private static final long serialVersionUID = 1L;

    /** Speed of light in m/s. */
    public static final double C = 299792458.0;
    /** Planck constant in J s. */
    public static final double PLANCK = 6.62607015e-34;
    /** Boltzmann constant in J/K. */
    public static final double BOLTZMANN = 1.380649e-23;

    /** Scale K fitted to [ERAERDS10] Fig. 1 (see the class description). */
    public static final double DEFAULT_SCALE = 1.2943037e-16;
    /** Fibre temperature in K used in the fit. */
    public static final double DEFAULT_TEMPERATURE_K = 300.0;
    /** Pump wavelength of the reference measurement in nm. */
    public static final double REFERENCE_PUMP_NM = 1550.0;

    private static final double NU_REFERENCE_HZ = C / (REFERENCE_PUMP_NM * 1e-9);

    private final double scale;
    private final double temperatureK;
    /** Parte 48: optional empirical correction of the anti-Stokes side (null = NONE, also for old save states). */
    private final AntiStokesCorrection antiStokesCorrection;

    /**
     * Parte 48: correction of the anti-Stokes cross-section by measurements.
     *
     * <p>{@link #MEASURED} multiplies the anti-Stokes side by a factor interpolated linearly in the frequency offset:
     * 1 up to 10 THz (where the model already agrees with [ERAERDS10], VMB-2, and with [CHAPURAN09] at 9.9 THz),
     * 2.3 at 17 THz and 2.2 at 24.7 THz (the measured coefficients of [CHAPURAN09] Table 1, mean of the four SMF-28
     * spools, are 2.3 and 2.2 times the model), 1.1 at 27.6 THz ([NWEKE05], 1465-1490 nm pump into 1310 nm) and 1
     * from 30 THz on. The Stokes side is unchanged. It is an empirical correction of measured SMF-28 fibres: the
     * shape of the gain profile agrees with [HOLLENBECK02] there, so the cause is not identified (fibre dopants or
     * phonon population); see docs/multibanda/VALIDACAO_LITERATURA.md.</p>
     */
    public enum AntiStokesCorrection {
        NONE, MEASURED;

        /** nenhuma | medida (also none | measured). */
        public static AntiStokesCorrection parse(String s) {
            final String v = s == null ? "" : s.trim().toLowerCase(java.util.Locale.ROOT);
            if (v.isEmpty() || v.equals("nenhuma") || v.equals("none")) return NONE;
            if (v.equals("medida") || v.equals("measured")) return MEASURED;
            throw new IllegalArgumentException("antiStokesCorrection must be nenhuma or medida: " + s);
        }
    }

    /** Points (offset THz, factor) of {@link AntiStokesCorrection#MEASURED}. */
    private static final double[][] MEASURED_POINTS = {{10.0, 1.0}, {17.0, 2.3}, {24.7, 2.2}, {27.6, 1.1}, {30.0, 1.0}};

    /** Factor of the anti-Stokes side at {@code offsetThz} (absolute value) for the measured correction. */
    public static double measuredAntiStokesFactor(double offsetThz) {
        final double x = Math.abs(offsetThz);
        final double[][] p = MEASURED_POINTS;
        if (x <= p[0][0] || x >= p[p.length - 1][0]) return 1.0;
        for (int i = 1; i < p.length; i++) {
            if (x <= p[i][0]) {
                return p[i - 1][1] + (p[i][1] - p[i - 1][1]) * (x - p[i - 1][0]) / (p[i][0] - p[i - 1][0]);
            }
        }
        return 1.0;
    }

    /**
     * @param scale cross-section scale K (use {@link #DEFAULT_SCALE} unless re-fitting to another fibre)
     * @param temperatureK fibre temperature in K
     */
    public SpontaneousRamanModel(double scale, double temperatureK) {
        this(scale, temperatureK, AntiStokesCorrection.NONE);
    }

    /** Parte 48: same model with the given anti-Stokes correction. */
    public SpontaneousRamanModel(double scale, double temperatureK, AntiStokesCorrection antiStokesCorrection) {
        if (!(scale >= 0.0) || Double.isInfinite(scale)) {
            throw new IllegalArgumentException("scale must be finite and >= 0");
        }
        if (!(temperatureK > 0.0) || Double.isInfinite(temperatureK)) {
            throw new IllegalArgumentException("temperatureK must be finite and > 0");
        }
        this.scale = scale;
        this.temperatureK = temperatureK;
        this.antiStokesCorrection = antiStokesCorrection == null ? AntiStokesCorrection.NONE : antiStokesCorrection;
    }

    /** SSMF at 300 K with the cross-section fitted to [ERAERDS10]. */
    public static SpontaneousRamanModel standard() {
        return new SpontaneousRamanModel(DEFAULT_SCALE, DEFAULT_TEMPERATURE_K);
    }

    /** Parte 48: anti-Stokes correction in use. */
    public AntiStokesCorrection getAntiStokesCorrection() {
        return antiStokesCorrection == null ? AntiStokesCorrection.NONE : antiStokesCorrection;
    }

    /** Parte 48: same model with another anti-Stokes correction. */
    public SpontaneousRamanModel withAntiStokesCorrection(AntiStokesCorrection c) {
        return new SpontaneousRamanModel(scale, temperatureK, c);
    }

    /** Cross-section scale K. */
    public double getScale() { return scale; }

    /** Fibre temperature in K. */
    public double getTemperatureK() { return temperatureK; }

    /**
     * SpRS cross-section from a classical channel (pump) into the QCh band.
     *
     * @param pumpNm wavelength of the classical channel in nm
     * @param signalNm wavelength of the quantum channel in nm
     * @return rho in 1/(km nm); zero when both wavelengths coincide or the offset exceeds 42 THz
     */
    public double crossSectionPerKmNm(double pumpNm, double signalNm) {
        requirePositive(pumpNm, "pumpNm");
        requirePositive(signalNm, "signalNm");
        final double nuP = C / (pumpNm * 1e-9);
        final double nuQ = C / (signalNm * 1e-9);
        final double perHz = scale * spectralShape(nuP - nuQ);
        final double lambdaQm = signalNm * 1e-9;
        return perHz * (C / (lambdaQm * lambdaQm)) * 1e-9 * (nuP / NU_REFERENCE_HZ);
    }

    /**
     * g0 times the phonon population factor.
     *
     * @param offsetHz nu_pump - nu_signal in Hz (positive: Stokes, negative: anti-Stokes)
     */
    double spectralShape(double offsetHz) {
        final double x = PLANCK * Math.abs(offsetHz) / (BOLTZMANN * temperatureK);
        if (x == 0.0) {
            return 0.0;
        }
        final double nTh = 1.0 / Math.expm1(x);
        if (offsetHz > 0.0) {
            return RamanGainProfile.g0(offsetHz) * (nTh + 1.0);
        }
        final double corr = getAntiStokesCorrection() == AntiStokesCorrection.MEASURED
                ? measuredAntiStokesFactor(offsetHz / 1e12) : 1.0;
        return RamanGainProfile.g0(offsetHz) * nTh * corr;
    }

    // ------------------------------------------------------------------ effective lengths (km)

    /**
     * Forward SpRS, same core, exact form: (e^{-a_q L} - e^{-a_c L}) / (a_c - a_q).
     *
     * @param alphaClassical loss at the classical wavelength in neper/km
     * @param alphaQuantum loss at the QCh wavelength in neper/km
     * @param lengthKm fibre length in km
     * @return effective length in km
     */
    public static double forwardLengthKm(double alphaClassical, double alphaQuantum, double lengthKm) {
        checkLength(lengthKm);
        return Math.exp(-alphaQuantum * lengthKm) * expm1Over(alphaQuantum - alphaClassical, lengthKm);
    }

    /**
     * Forward SpRS, same core, in the form of [MEHDI24]/[DIBAJ25]: L e^{-a L} (equal-loss approximation of
     * {@link #forwardLengthKm}). {@link MultiBandQkdLinkModel} passes the loss of the classical channel, as in the
     * papers' equation.
     *
     * @param alpha loss in neper/km
     * @param lengthKm fibre length in km
     */
    public static double forwardLengthPaperKm(double alpha, double lengthKm) {
        checkLength(lengthKm);
        return lengthKm * Math.exp(-alpha * lengthKm);
    }

    /**
     * Forward SpRS from a neighbour core, [CAI20] eq. 11 (both crosstalk/SpRS orderings):
     * e^{-a_q L} { [e^{(a_q - a_c) L} - 1]/(a_q - a_c) - [e^{(a_q - a_c - 2h) L} - 1]/(a_q - a_c - 2h) }.
     *
     * @param couplingPerKm power coupling coefficient h between the two cores in 1/km
     */
    public static double intercoreForwardLengthKm(double alphaClassical, double alphaQuantum, double couplingPerKm,
            double lengthKm) {
        checkLength(lengthKm);
        final double d = alphaQuantum - alphaClassical;
        return Math.exp(-alphaQuantum * lengthKm)
                * (expm1Over(d, lengthKm) - expm1Over(d - 2.0 * couplingPerKm, lengthKm));
    }

    /**
     * (e^{x L} - 1) / x, with the limit L for x = 0. Accurate for small |x L| (uses expm1).
     */
    static double expm1Over(double x, double lengthKm) {
        final double xl = x * lengthKm;
        if (Math.abs(xl) < 1e-12) {
            return lengthKm * (1.0 + 0.5 * xl);
        }
        return Math.expm1(xl) / x;
    }

    private static void checkLength(double lengthKm) {
        if (!(lengthKm >= 0.0) || Double.isInfinite(lengthKm)) {
            throw new IllegalArgumentException("lengthKm must be finite and >= 0");
        }
    }

    private static void requirePositive(double v, String name) {
        if (!(v > 0.0) || Double.isInfinite(v)) {
            throw new IllegalArgumentException(name + " must be finite and > 0");
        }
    }
}
